// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != c.ceoAddress());
        bool reverted;
        vm.prank(caller);
        try c.DrugDealer() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted);
    }
}
